function answerString(word, numFriends) {
  if (numFriends === 1) return word;
  const n = word.length;
  // i is the start of the best suffix so far, j a challenger, and k how many letters they share.
  let i = 0;
  let j = 1;
  let k = 0;
  while (j + k < n) {
    if (word[i + k] === word[j + k]) {
      k++;
    } else if (word[i + k] > word[j + k]) {
      j = j + k + 1;
      k = 0;
    } else {
      i = Math.max(i + k + 1, j);
      j = i + 1;
      k = 0;
    }
  }
  // The other numFriends - 1 pieces need at least one letter each.
  return word.slice(i, i + n - numFriends + 1);
}

brute:
function answerString(word, numFriends) {
  const n = word.length;
  let best = '';
  // Try every substring word[a..b) as a piece. The a letters before it and the n - b after it must form the
  // other numFriends - 1 pieces: a non-empty side makes between 1 and its length pieces, an empty side none.
  for (let a = 0; a < n; a++) {
    for (let b = a + 1; b <= n; b++) {
      const after = n - b;
      const fewest = (a > 0 ? 1 : 0) + (after > 0 ? 1 : 0);
      if (fewest <= numFriends - 1 && numFriends - 1 <= a + after) {
        const piece = word.slice(a, b);
        if (piece > best) best = piece;
      }
    }
  }
  return best;
}

