function generate(rand, size) {
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 10);
  // Few distinct letters make suffixes share long beginnings, where comparisons are tricky.
  const letters = size === 'large' ? 2 + Math.floor(rand() * 3) : 1 + Math.floor(rand() * 3);
  const letter = () => String.fromCharCode(97 + Math.floor(rand() * letters));
  let word = '';
  if (size === 'large' && rand() < 0.5) {
    // A repeated block with occasional single letters, so that many suffixes start alike.
    const block = Array.from({ length: 1 + Math.floor(rand() * 20) }, letter).join('');
    while (word.length < n) word += rand() < 0.1 ? letter() : block;
    word = word.slice(0, n);
  } else {
    word = Array.from({ length: n }, letter).join('');
  }
  const choice = rand();
  const numFriends = choice < 0.15 ? 1 : choice < 0.3 ? 2 : 1 + Math.floor(rand() * n);
  return [word, numFriends];
}
